function originalExam(ch){
 const L=revL, key='originalExam:'+ch, rs=readerStore(),url='book-tests/'+ch+'.pdf';
 app.innerHTML='<button id="exBack">'+L('رجع للفصل','Zum Kapitel')+'</button><section class="card"><span class="cap">Kapitel '+ch+' · 20 Punkte</span><h2>Kleiner Abschlusstest</h2><a href="'+url+'" target="_blank" rel="noopener">'+L('فتح أو تحميل ورقة الاختبار الأصلية PDF','Originalbogen als PDF öffnen')+'</a><img style="width:100%;height:auto;margin-top:1rem" src="book-tests/'+ch+'.jpg" alt="Abschlusstest Kapitel '+ch+'"><label for="exNotes">'+L('كتب أجوبتك برقم التمرين','Antworten mit Aufgabennummer')+'</label><textarea id="exNotes" rows="8" lang="de" dir="ltr"></textarea><button id="exPDF">'+L('وجد PDF بالأسئلة والأجوبة ديالي','PDF mit meinen Antworten erstellen')+'</button><div id="exFile"></div></section>';
 const box=$('#exNotes'),file=$('#exFile');let tmp;function clear(){if(tmp)URL.revokeObjectURL(tmp);tmp=null;file.replaceChildren()} box.value=rs.drafts[key]||'';box.oninput=()=>{rs.drafts[key]=box.value;save();clear()};$('#exBack').onclick=()=>{clear();chapter(ch)};$('#exPDF').onclick=async function(){this.disabled=true;clear();try{const doc=await PDFLib.PDFDocument.load(await (await fetch(url)).arrayBuffer());const cv=document.createElement('canvas');cv.width=1200;cv.height=1680;const ctx=cv.getContext('2d');let y=0;function start(){ctx.fillStyle='white';ctx.fillRect(0,0,1200,1680);ctx.fillStyle='black';ctx.font='29px Arial';ctx.fillText('Kapitel '+ch+' · Meine Antworten',65,90);y=155}async function flush(){const im=await doc.embedPng(cv.toDataURL());doc.addPage([600,840]).drawImage(im,{x:0,y:0,width:600,height:840})}start();for(let row of box.value.split('\n')){let line='';for(let char of row){if(ctx.measureText(line+char).width>1060){ctx.fillText(line,65,y);y+=45;line='';if(y>1580){await flush();start()}}line+=char}ctx.fillText(line,65,y);y+=45;if(y>1580){await flush();start()}}await flush();tmp=URL.createObjectURL(new Blob([await doc.save()],{type:'application/pdf'}));let a=document.createElement('a');a.href=tmp;a.target='_blank';a.textContent=L('فتح PDF وحفظو','PDF öffnen und speichern');file.append(a)}catch{file.textContent=L('تعذّر تجهيز الملف. عاود المحاولة.','Bitte erneut versuchen.')}finally{this.disabled=false}};window.scrollTo(0,0)}
